import{_ as r,o as a,c as e,a4 as o}from"./chunks/framework.DAD9IEko.js";const g=JSON.parse('{"title":"PP-10 维也纳整流器 - 知识检查","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-10 维也纳整流器 - 知识检查","tags":["motor-control"],"status":"learning","summary":"**模块编号：** PP-10 **题目数量：** 8 **验收目标：** 能说明 Vienna 整流器的三相 PFC 机理、电流环/电压环结构、中点平衡策略，以及前级母线对电机控制的影响。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-10-assessment.md","filePath":"content/motor/power-path/PP-10-assessment.md","lastUpdated":1783096495000}'),n={name:"content/motor/power-path/PP-10-assessment.md"};function s(d,t,h,i,l,p){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="pp-10-维也纳整流器-知识检查" tabindex="-1">PP-10 维也纳整流器 - 知识检查 <a class="header-anchor" href="#pp-10-维也纳整流器-知识检查" aria-label="Permalink to &quot;PP-10 维也纳整流器 - 知识检查&quot;">​</a></h1><p><strong>模块编号：</strong> PP-10<br><strong>题目数量：</strong> 8<br><strong>验收目标：</strong> 能说明 Vienna 整流器的三相 PFC 机理、电流环/电压环结构、中点平衡策略，以及前级母线对电机控制的影响。</p><hr><h2 id="_1-拓扑定位" tabindex="-1">1. 拓扑定位 <a class="header-anchor" href="#_1-拓扑定位" aria-label="Permalink to &quot;1. 拓扑定位&quot;">​</a></h2><p><strong>问题：</strong> Vienna 整流器属于哪类变换器？</p><p>A. 单相隔离 DC/DC<br> B. 三相三电平单向 PFC 整流器<br> C. 双向全桥逆变器<br> D. 无源二极管整流器</p><p><strong>答案：</strong> B</p><hr><h2 id="_2-单向功率流" tabindex="-1">2. 单向功率流 <a class="header-anchor" href="#_2-单向功率流" aria-label="Permalink to &quot;2. 单向功率流&quot;">​</a></h2><p><strong>问题：</strong> 为什么标准 Vienna 整流器通常不适合能量回馈到电网？</p><p><strong>参考答案：</strong> 其功率器件和二极管路径决定了主要功率流方向为 AC 到 DC，缺少完整可控的反向电流路径。若需要回馈，应使用有源前端 AFE 等双向拓扑。</p><hr><h2 id="_3-控制结构" tabindex="-1">3. 控制结构 <a class="header-anchor" href="#_3-控制结构" aria-label="Permalink to &quot;3. 控制结构&quot;">​</a></h2><p><strong>问题：</strong> Vienna PFC 的典型双环控制是什么？</p><p><strong>答案：</strong> 外环为直流母线电压环，产生有功电流幅值指令；内环为三相输入电流环，使输入电流跟踪与电网电压同相的正弦参考。</p><hr><h2 id="_4-功率因数与-thd" tabindex="-1">4. 功率因数与 THD <a class="header-anchor" href="#_4-功率因数与-thd" aria-label="Permalink to &quot;4. 功率因数与 THD&quot;">​</a></h2><p><strong>任务：</strong> 仿真额定负载下的输入电流。</p><p><strong>验收标准：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>指标</th><th>70% 阶段阈值</th></tr></thead><tbody><tr><td>功率因数 PF</td><td>&gt; 0.98</td></tr><tr><td>输入电流 THD</td><td>&lt; 8%</td></tr><tr><td>直流母线纹波</td><td>满足设计表，不超过目标值 10%</td></tr><tr><td>三相电流平衡</td><td>三相 RMS 偏差 &lt; 5%</td></tr></tbody></table></div><hr><h2 id="_5-中点平衡" tabindex="-1">5. 中点平衡 <a class="header-anchor" href="#_5-中点平衡" aria-label="Permalink to &quot;5. 中点平衡&quot;">​</a></h2><p><strong>问题：</strong> Vienna 整流器为什么也需要中点电压控制？</p><p><strong>参考答案：</strong> 输出侧上下母线电容构成分压中点，不同相电流和开关状态会导致中点充放电不均。中点偏移会引起器件应力不均、调制失真和母线电压利用率下降。</p><hr><h2 id="_6-与-pmsm-驱动关系" tabindex="-1">6. 与 PMSM 驱动关系 <a class="header-anchor" href="#_6-与-pmsm-驱动关系" aria-label="Permalink to &quot;6. 与 PMSM 驱动关系&quot;">​</a></h2><p><strong>问题：</strong> Vienna 前级母线跌落会如何影响 FOC？</p><p><strong>参考答案：</strong> 母线跌落会降低逆变器可用电压，导致电流环电压限幅提前出现，弱磁区能力下降，速度环可能饱和。lxfoc 侧必须读取 <code>vbus</code> 并执行电压限幅、保护和必要的转矩降额。</p><hr><h2 id="_7-故障诊断" tabindex="-1">7. 故障诊断 <a class="header-anchor" href="#_7-故障诊断" aria-label="Permalink to &quot;7. 故障诊断&quot;">​</a></h2><p><strong>问题：</strong> 输入电流过零附近畸变明显，优先检查哪些问题？</p><p><strong>参考答案：</strong> 电流采样偏置、PLL 相位、死区/最小脉宽、调制符号、输入电感参数、过零附近电流环带宽和电压前馈。</p><hr><h2 id="_8-发布边界" tabindex="-1">8. 发布边界 <a class="header-anchor" href="#_8-发布边界" aria-label="Permalink to &quot;8. 发布边界&quot;">​</a></h2><p><strong>问题：</strong> PP-10 在 70% 阶段达到 <code>reviewed</code> 与达到 <code>verified</code> 的区别是什么？</p><p><strong>答案：</strong> <code>reviewed</code> 需要完成权威来源、推导和仿真闭环；<code>verified</code> 还必须有低风险台架或实物实验 trace，并能生成 PF、THD、纹波和故障标志等实测报告。</p><hr><h2 id="评分" tabindex="-1">评分 <a class="header-anchor" href="#评分" aria-label="Permalink to &quot;评分&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th style="text-align:right;">得分</th><th>评价</th></tr></thead><tbody><tr><td style="text-align:right;">7-8</td><td>可进入 Vienna 工程化和 PFC-电机联合调试</td></tr><tr><td style="text-align:right;">5-6</td><td>需要补充中点平衡和母线动态</td></tr><tr><td style="text-align:right;">&lt;5</td><td>需要重学三相 PFC 与整流基础</td></tr></tbody></table></div>',39)])])}const P=r(n,[["render",s]]);export{g as __pageData,P as default};
